// Budget og Mad – faste opskrifter. Klassiske retter skrevet ud fra kendte opskrifter.
// Fotos: se kilder.txt. foto:'' betyder, at der ikke findes et ægte gratis foto af retten endnu.
var STD_OPSKRIFTER=[
{id:'std-frikadeller',kat:'Kød & fars',navn:'Frikadeller',foto:'fotos/retter/frikadeller.jpg',tid:45,portioner:4,tags:['dansk'],
 ing:['500 g hakket svinekød','1 løg','1 æg','1 dl mælk','3 spsk hvedemel','1 tsk salt','1 knsp peber','2 spsk smør'],
 trin:['Riv eller hak løget meget fint.','Rør kødet med salt i en skål. Rør løg, æg og mel i.','Rør mælken i lidt ad gangen, til farsen er samlet og lidt blank.','Lad farsen hvile 15 minutter i køleskabet.','Form frikadeller med en spiseske. Dyp skeen i det smeltede smør imellem.','Steg dem ved middel varme ca. 5–6 minutter på hver side, til de er gennemstegte.','Server med kartofler og sovs, rødkål eller kartoffelsalat.']},
{id:'std-boller-i-karry',kat:'Ris, korn & grød',navn:'Boller i karry',foto:'fotos/retter/boller.jpg',tid:50,portioner:4,tags:['dansk'],
 ing:['500 g hakket svinekød','1 løg','1 æg','3 spsk hvedemel','1 dl mælk','1 tsk salt','2 spsk smør','2 spsk karry','3 spsk hvedemel','1 dl madlavningsfløde','3 dl ris'],
 trin:['Hak løget fint. Rør kød, salt, halvdelen af løget, æg, 3 spsk mel og mælk til en fars.','Kog ca. 1 liter let saltet vand. Form små boller med en teske og kog dem 8–10 minutter. Tag dem op, og gem 7 dl af kogevandet.','Kog risene efter pakken.','Smelt smørret i en gryde. Svits resten af løget og karryen et minut.','Rør 3 spsk mel i. Pisk kogevandet i lidt ad gangen, og lad sovsen koge 5 minutter.','Rør fløden i, og smag til med salt. Kom bollerne i sovsen og varm dem igennem.','Server med ris.']},
{id:'std-biksemad',kat:'Kød & fars',navn:'Biksemad',foto:'fotos/retter/biksemad.jpg',tid:30,portioner:4,tags:['dansk','hurtig','rester'],
 ing:['750 g kogte kartofler','400 g rester af kød eller pølser','2 løg','2 spsk smør','4 æg','1 tsk salt','1 knsp peber'],
 trin:['Skær kartofler og kød i små tern. Hak løgene.','Steg kartoflerne i smør på en stor pande, til de er gyldne. Det tager ca. 10 minutter.','Kom løg og kød på, og steg 5–8 minutter mere. Smag til med salt og peber.','Steg et spejlæg til hver.','Server med spejlæg, rødbeder og ketchup.']},
{id:'std-aeggekage',kat:'Æg & hurtigt',navn:'Æggekage med bacon',foto:'',tid:25,portioner:4,tags:['dansk','hurtig'],
 ing:['8 æg','2 dl mælk','2 spsk hvedemel','200 g bacon','2 tomater','1 bundt purløg','1 tsk salt','1 knsp peber'],
 trin:['Steg baconen sprød på en pande. Læg den på køkkenrulle.','Pisk æg, mælk, mel, salt og peber sammen.','Hæld æggemassen på panden med lidt af fedtet. Læg låg på, og lad den stivne ved svag varme i 10–15 minutter.','Skub forsigtigt kanten ind en gang imellem, så den ikke brænder på.','Top med bacon, tomatbåde og klippet purløg. Server med rugbrød.']},
{id:'std-braendende-kaerlighed',kat:'Kød & fars',navn:'Brændende kærlighed',foto:'fotos/retter/braendende.jpg',tid:35,portioner:4,tags:['dansk'],
 ing:['1 kg kartofler','2 dl mælk','50 g smør','250 g bacon','2 løg','1 tsk salt','1 knsp peber'],
 trin:['Skræl kartoflerne, og kog dem møre i ca. 20 minutter.','Skær bacon i tern og løg i skiver. Steg dem sprøde og gyldne.','Hæld vandet fra kartoflerne. Mos dem med varm mælk og smør. Smag til med salt og peber.','Læg mosen på tallerkenen, og top med bacon og løg.','Server gerne med rødbeder.']},
{id:'std-millionboef',kat:'Kød & fars',navn:'Millionbøf med kartoffelmos',foto:'fotos/retter/millionbof.jpg',tid:35,portioner:4,tags:['dansk'],
 ing:['500 g hakket oksekød','1 løg','2 spsk hvedemel','5 dl vand','1 stk bouillonterning','1 spsk tomatpuré','1 kg kartofler','2 dl mælk','25 g smør','1 tsk salt','1 knsp peber'],
 trin:['Skræl kartoflerne, og sæt dem over at koge i ca. 20 minutter.','Brun kødet i en gryde, og del det i små stykker. Kom hakket løg i.','Drys melet over, og rør rundt.','Tilsæt vand, bouillonterning og tomatpuré. Lad det simre 15–20 minutter.','Mos kartoflerne med varm mælk og smør.','Smag kødsovsen til med salt og peber, og server den med mosen.']},
{id:'std-hakkeboef',kat:'Kød & fars',navn:'Hakkebøf med bløde løg',foto:'',tid:35,portioner:4,tags:['dansk'],
 ing:['500 g hakket oksekød','3 løg','2 spsk smør','3 dl vand','1 stk bouillonterning','1 kg kartofler','1 tsk salt','1 knsp peber'],
 trin:['Kog kartoflerne møre i ca. 20 minutter.','Form kødet til 4 bøffer. Drys med salt og peber.','Skær løgene i tynde skiver. Steg dem bløde og gyldne i smør i ca. 15 minutter, og tag dem af panden.','Steg bøfferne 3–4 minutter på hver side.','Kom vand og bouillonterning på panden, og lad det koge op til en sovs.','Server bøfferne med løg, sovs og kartofler.']},
{id:'std-porresuppe',kat:'Supper',navn:'Kartoffel-porresuppe',foto:'fotos/retter/porresuppe.jpg',tid:40,portioner:4,tags:['vegetar'],
 ing:['1 kg kartofler','3 porrer','1 løg','2 spsk smør','1,5 l vand','2 stk bouillonterning','1 dl madlavningsfløde','1 tsk salt','1 knsp peber'],
 trin:['Rens porrerne, og skær dem i skiver. Skræl kartoflerne, og skær dem i tern. Hak løget.','Svits løg og porrer i smør i 5 minutter.','Kom kartofler, vand og bouillon i. Kog i ca. 20 minutter, til kartoflerne er møre.','Blend suppen, eller mos den med et piskeris.','Rør fløden i, og smag til med salt og peber. Server med brød.']},
{id:'std-gule-aerter',kat:'Supper',navn:'Gule ærter',foto:'fotos/retter/gulearter.jpg',tid:90,portioner:4,tags:['dansk'],
 ing:['500 g gule ærter','1,5 l vand','1 løg','3 gulerødder','2 porrer','400 g medisterpølse','1 tsk timian','1 tsk salt'],
 trin:['Skyl de flækkede ærter i koldt vand.','Kog ærterne i vandet med det hakkede løg i 45–60 minutter. Fjern skummet undervejs.','Skær gulerødder og porrer i stykker, og kom dem i. Kog 20 minutter mere.','Kog eller steg pølsen, og skær den i skiver.','Smag suppen til med timian og salt. Server med pølsen, sennep og rugbrød.']},
{id:'std-risengroed',kat:'Ris, korn & grød',navn:'Risengrød',foto:'fotos/retter/risengrod.jpg',tid:45,portioner:4,tags:['dansk','vegetar'],
 ing:['2,5 dl grødris','2 dl vand','1 l sødmælk','0,5 tsk salt','2 spsk sukker','1 tsk kanel','25 g smør'],
 trin:['Kog risene i vandet i 2 minutter.','Hæld mælken i, og bring det i kog under omrøring.','Skru helt ned, læg låg på, og lad grøden simre i 35–40 minutter. Rør tit, så den ikke brænder på.','Rør salt i.','Server med kanelsukker og en klat smør.']},
{id:'std-oellebroed',kat:'Ris, korn & grød',navn:'Øllebrød',foto:'',tid:25,portioner:4,tags:['dansk','vegetar','rester'],
 ing:['300 g rugbrød','5 dl hvidtøl','5 dl vand','50 g sukker','1 stk citron','2 dl mælk'],
 trin:['Bræk rugbrødet i stykker. Læg det i blød i vand og hvidtøl i nogle timer eller natten over.','Kog det op, og lad det koge ca. 10 minutter under omrøring.','Pisk eller blend det glat.','Smag til med sukker og revet citronskal.','Server med kold mælk. Godt til gammelt rugbrød.']},
{id:'std-pandekager',kat:'Æg & hurtigt',navn:'Pandekager',foto:'fotos/retter/pandekager.jpg',tid:30,portioner:4,tags:['vegetar','hurtig'],
 ing:['3 æg','2,5 dl hvedemel','5 dl mælk','1 spsk sukker','0,5 tsk salt','25 g smør'],
 trin:['Pisk mel og mælk sammen lidt ad gangen, så der ikke kommer klumper.','Pisk æg, sukker og salt i. Lad dejen hvile 15 minutter.','Smelt lidt smør på en pande ved god varme.','Hæld et tyndt lag dej på, og steg ca. 1 minut på hver side.','Server med sukker, syltetøj eller frugt.']},
{id:'std-kylling-i-karry',kat:'Ris, korn & grød',navn:'Kylling i karry',foto:'fotos/retter/kyllingkarry.jpg',tid:35,portioner:4,tags:[],
 ing:['500 g kyllingebryst','1 løg','2 spsk olie','2 spsk karry','1 æble','2 spsk hvedemel','4 dl vand','1 stk bouillonterning','1 dl madlavningsfløde','3 dl ris'],
 trin:['Kog risene efter pakken.','Skær kyllingen i tern, og brun den i olie. Tag den op.','Svits hakket løg og karry i gryden i et minut.','Drys melet over, og pisk vand og bouillonterning i.','Kom æble i tern og kyllingen i. Lad det simre ca. 10 minutter, til kyllingen er gennemstegt.','Rør fløden i, smag til, og server med ris.']},
{id:'std-spaghetti',kat:'Pasta & nudler',navn:'Spaghetti med kødsovs',foto:'fotos/retter/spaghetti.jpg',tid:35,portioner:4,tags:[],
 ing:['500 g hakket oksekød','1 løg','2 fed hvidløg','2 gulerødder','2 dåser hakkede tomater','2 spsk tomatpuré','1 tsk oregano','400 g spaghetti','1 tsk salt','1 knsp peber'],
 trin:['Brun kødet i en gryde.','Kom hakket løg, hvidløg og revne gulerødder i, og steg et par minutter.','Tilsæt tomater, tomatpuré og oregano. Lad det simre i 20 minutter.','Kog spaghettien efter pakken.','Smag sovsen til med salt og peber. Server med revet ost, hvis du har det.']},
{id:'std-chili-sin-carne',kat:'Grønt & vegetar',navn:'Chili sin carne',foto:'fotos/retter/chili.jpg',tid:35,portioner:4,tags:['vegetar'],
 ing:['1 løg','2 fed hvidløg','1 stk rød peberfrugt','2 gulerødder','2 spsk olie','2 tsk chilipulver','1 tsk spidskommen','2 dåser hakkede tomater','2 dåser kidneybønner','1 dåse majs','3 dl ris','1 tsk salt'],
 trin:['Kog risene efter pakken.','Hak løg og hvidløg. Skær peberfrugt og gulerødder i små tern.','Svits grøntsagerne i olie i 5 minutter. Rør chili og spidskommen i.','Kom tomater, skyllede bønner og majs i.','Lad det simre i 20 minutter. Smag til med salt.','Server med ris og gerne lidt yoghurt naturel.']},
{id:'std-havregroed',kat:'Ris, korn & grød',navn:'Havregrød',foto:'fotos/retter/havregrod.jpg',tid:10,portioner:2,tags:['dansk','vegetar','hurtig'],
 ing:['2 dl havregryn','4 dl vand','1 knsp salt','1 æble','2 dl mælk'],
 trin:['Kom havregryn og vand i en gryde.','Kog op under omrøring, og lad grøden simre 3–5 minutter.','Rør salt i.','Top med æble i tern og kold mælk. Kanel er også godt.']},
{id:'std-lasagne',kat:'Pasta & nudler',navn:'Lasagne',foto:'fotos/retter/lasagne.jpg',tid:75,portioner:4,tags:[],
 ing:['500 g hakket oksekød','1 løg','2 fed hvidløg','2 gulerødder','2 dåser hakkede tomater','2 spsk tomatpuré','1 tsk oregano','250 g lasagneplader','50 g smør','4 spsk hvedemel','7 dl mælk','100 g revet ost','1 tsk salt','1 knsp peber'],
 trin:['Brun kødet i en gryde. Kom hakket løg, hvidløg og revne gulerødder i.','Tilsæt tomater, tomatpuré og oregano. Lad kødsovsen simre 15 minutter. Smag til med salt og peber.','Lav hvid sovs: Smelt smørret, rør melet i, og pisk mælken i lidt ad gangen. Kog 3 minutter under omrøring.','Læg lag i et ovnfast fad: kødsovs, lasagneplader, hvid sovs. Gentag, og slut med hvid sovs.','Drys osten over. Bag ved 200 °C i ca. 35 minutter, til pladerne er møre.']},
{id:'std-tomatsuppe',kat:'Supper',navn:'Tomatsuppe',foto:'fotos/retter/tomatsuppe.jpg',tid:30,portioner:4,tags:['vegetar','hurtig'],
 ing:['1 løg','2 fed hvidløg','2 spsk olie','2 dåser hakkede tomater','1 l vand','1 stk bouillonterning','1 dl madlavningsfløde','1 tsk sukker','1 tsk salt','1 knsp peber'],
 trin:['Hak løg og hvidløg, og svits dem i olie i 3 minutter.','Kom tomater, vand og bouillon i. Kog i 15 minutter.','Blend suppen glat.','Rør fløde og sukker i, og smag til med salt og peber.','Server med brød – eller kogte makaroner i suppen.']},
{id:'std-linsesuppe',kat:'Supper',navn:'Rød linsesuppe',foto:'fotos/retter/linsesuppe.jpg',tid:30,portioner:4,tags:['vegetar','hurtig'],
 ing:['250 g røde linser','1 løg','2 gulerødder','2 fed hvidløg','2 spsk olie','2 tsk karry','1 dåse hakkede tomater','1 l vand','1 stk bouillonterning','1 tsk salt'],
 trin:['Hak løg og hvidløg, og skær gulerødderne i små tern.','Svits grøntsagerne i olie med karry i 3 minutter.','Skyl linserne, og kom dem i gryden med tomater, vand og bouillon.','Kog i 15–20 minutter, til linserne er helt møre.','Blend suppen, eller lad den være grov. Smag til med salt.']},
{id:'std-stegt-ris',kat:'Ris, korn & grød',navn:'Stegte ris med æg',foto:'fotos/retter/stegtris.jpg',tid:20,portioner:2,tags:['vegetar','hurtig','rester'],
 ing:['5 dl kogte ris','3 æg','1 løg','200 g frosne ærter','2 spsk olie','3 spsk soja'],
 trin:['Brug gerne ris fra i går – de bliver bedst.','Hak løget, og steg det i olie på en stor pande.','Kom ris og ærter på, og steg ved høj varme i 5 minutter.','Skub risene til side, slå æggene ud på panden, og rør dem til de stivner.','Bland det hele, og smag til med soja.']},
{id:'std-carbonara',kat:'Pasta & nudler',navn:'Pasta carbonara',foto:'fotos/retter/carbonara.jpg',tid:20,portioner:4,tags:['hurtig'],
 ing:['400 g spaghetti','200 g bacon','3 æg','100 g revet parmesan','1 knsp peber','1 tsk salt'],
 trin:['Kog spaghettien i saltet vand efter pakken. Gem 1 dl af kogevandet.','Steg baconen sprød i tern.','Pisk æg og ost sammen i en skål.','Hæld vandet fra pastaen, og kom den på panden med baconen. Tag panden af varmen.','Rør æggeblandingen og lidt kogevand i, så det bliver cremet. Drys med peber.']},
{id:'std-shakshuka',kat:'Æg & hurtigt',navn:'Shakshuka',foto:'fotos/retter/shakshuka.jpg',tid:25,portioner:2,tags:['vegetar','hurtig'],
 ing:['1 løg','1 stk rød peberfrugt','2 fed hvidløg','2 spsk olie','1 tsk spidskommen','1 tsk paprika','1 dåse hakkede tomater','4 æg','1 tsk salt'],
 trin:['Hak løg, peberfrugt og hvidløg, og steg dem bløde i olie.','Rør krydderierne i, og kom tomaterne på. Lad det simre 8 minutter.','Lav 4 huller i sovsen, og slå et æg ud i hvert.','Læg låg på, og lad æggene stivne i 5–7 minutter.','Server med brød direkte fra panden.']},
{id:'std-tacos',kat:'Mexicansk & street food',navn:'Tacos',foto:'fotos/retter/tacos.jpg',tid:25,portioner:4,tags:['hurtig'],
 ing:['500 g hakket oksekød','1 løg','2 tsk chilipulver','1 tsk spidskommen','1 dåse hakkede tomater','8 stk tortillas','1 stk iceberg','2 tomater','100 g revet ost','1 tsk salt'],
 trin:['Brun kødet med hakket løg.','Rør krydderier og tomater i, og lad det simre 10 minutter. Smag til med salt.','Snit salat og tomater.','Varm tortillas på en tør pande.','Fyld tortillas med kød, salat, tomat og ost.']},
{id:'std-pizza',kat:'Mexicansk & street food',navn:'Hjemmelavet pizza',foto:'fotos/retter/pizza.jpg',tid:60,portioner:4,tags:['vegetar'],
 ing:['5 dl hvedemel','2,5 dl vand','25 g gær','2 spsk olie','1 tsk salt','1 dåse hakkede tomater','1 tsk oregano','200 g revet mozzarella'],
 trin:['Rør gæren ud i lunkent vand. Tilsæt olie, salt og mel, og ælt dejen smidig.','Lad dejen hæve tildækket i 30 minutter.','Rul dejen ud på en bageplade med bagepapir.','Smør tomat med oregano på, og drys osten over. Kom gerne rester af grøntsager på.','Bag ved 225 °C i 12–15 minutter.']},
{id:'std-fiskefrikadeller',kat:'Fisk',navn:'Fiskefrikadeller',foto:'',tid:35,portioner:4,tags:['dansk'],
 ing:['500 g fiskefars','1 løg','1 æg','2 spsk hvedemel','1 dl mælk','2 spsk smør','1 kg kartofler','1 stk citron','1 tsk salt'],
 trin:['Kog kartoflerne møre i ca. 20 minutter.','Rør fiskefarsen med revet løg, æg, mel og mælk. Smag til med salt.','Form frikadeller med en spiseske.','Steg dem i smør ved middel varme i ca. 4 minutter på hver side.','Server med kartofler, citronbåde og gerne remoulade.']},
{id:'std-stegt-flaesk',kat:'Kød & fars',navn:'Stegt flæsk med persillesovs',foto:'',tid:45,portioner:4,tags:['dansk'],
 ing:['800 g skiver af stegeflæsk','1 kg kartofler','30 g smør','3 spsk hvedemel','5 dl mælk','1 bundt persille','1 tsk salt','1 knsp peber'],
 trin:['Kog kartoflerne møre i ca. 20 minutter.','Drys flæsket med salt, og steg det sprødt på en pande eller i ovnen ved 200 °C i ca. 25 minutter.','Lav sovsen: Smelt smørret, rør melet i, og pisk mælken i lidt ad gangen. Kog 5 minutter.','Rør hakket persille i sovsen, og smag til med salt og peber.','Server flæsk med kartofler og persillesovs.']},
{id:'std-wraps',kat:'Mexicansk & street food',navn:'Kyllingewraps',foto:'fotos/retter/wraps.jpg',tid:25,portioner:4,tags:['hurtig'],
 ing:['400 g kyllingebryst','1 spsk olie','1 tsk paprika','8 stk tortillas','1 stk iceberg','2 tomater','1 agurk','2 dl creme fraiche','1 tsk salt'],
 trin:['Skær kyllingen i strimler, krydr med paprika og salt, og steg dem gennem i olie.','Snit salat, tomat og agurk.','Varm tortillas kort på en tør pande.','Smør creme fraiche på, og fyld med kylling og grønt.','Rul dem sammen – perfekt som madpakke.']},
{id:'std-pasta-pesto',kat:'Pasta & nudler',navn:'Pasta med pesto',foto:'fotos/retter/pesto.jpg',tid:15,portioner:4,tags:['vegetar','hurtig'],
 ing:['400 g pasta','1 glas grøn pesto','200 g frosne ærter','50 g revet parmesan','1 tsk salt'],
 trin:['Kog pastaen i saltet vand efter pakken. Kom ærterne i de sidste 2 minutter.','Gem lidt kogevand, og hæld resten fra.','Rør pesto og lidt kogevand i pastaen.','Drys osten over og server.']},
{id:'std-kyllingesuppe',kat:'Supper',navn:'Kyllingesuppe med nudler',foto:'',tid:35,portioner:4,tags:[],
 ing:['400 g kyllingebryst','1 løg','3 gulerødder','2 stilke selleri','1,5 l vand','2 stk bouillonterning','150 g nudler','1 tsk salt'],
 trin:['Hak løget, og skær gulerødder og selleri i skiver.','Kog vand og bouillon op, og kom grøntsagerne i. Kog 10 minutter.','Skær kyllingen i tern, kom den i, og kog i 10 minutter, til den er gennemkogt.','Kom nudlerne i de sidste 4 minutter.','Smag til med salt.']},
{id:'std-aeblecrumble',kat:'Kage & dessert',navn:'Æblecrumble',foto:'fotos/retter/aeblecrumble.jpg',tid:40,portioner:4,tags:['vegetar'],
 ing:['6 æbler','2 spsk sukker','1 tsk kanel','100 g hvedemel','100 g havregryn','100 g sukker','100 g smør'],
 trin:['Skræl æblerne, skær dem i både, og læg dem i et ovnfast fad. Drys med sukker og kanel.','Smuldr mel, havregryn, sukker og smør sammen med fingrene.','Fordel smuldret over æblerne.','Bag ved 200 °C i ca. 25 minutter, til toppen er gylden.','Server lun – gerne med lidt yoghurt.']},
{id:'std-kyllingepasta',kat:'Pasta & nudler',navn:'Cremet kyllingepasta med bacon og champignon',foto:'fotos/retter/kyllingpasta.jpg',tid:30,portioner:4,tags:['hurtig'],
 ing:['400 g pasta','400 g kyllingebryst','150 g bacon','250 g champignon','1 løg','2 fed hvidløg','1 spsk olie','2,5 dl madlavningsfløde','50 g revet parmesan','1 tsk salt','1 knsp peber'],
 trin:['Kog pastaen i saltet vand efter pakken.','Skær kylling i tern, og steg den gennem i olie. Tag den af panden.','Steg bacon i tern, og kom champignon i skiver, hakket løg og hvidløg på.','Hæld fløden på, og lad det simre 3 minutter. Kom kyllingen i igen.','Vend pastaen i sovsen, drys ost over, og smag til med salt og peber.']},
{id:'std-wok',kat:'Pasta & nudler',navn:'Wok med kylling, grøntsager og nudler',foto:'fotos/retter/wok.jpg',tid:25,portioner:4,tags:['hurtig'],
 ing:['250 g nudler','400 g kyllingebryst','2 spsk olie','1 løg','2 gulerødder','1 stk rød peberfrugt','200 g broccoli','2 fed hvidløg','4 spsk soja','1 spsk sød chilisauce'],
 trin:['Kog nudlerne efter pakken, og skyl dem i koldt vand.','Skær kylling og grøntsager i tynde strimler.','Steg kyllingen ved høj varme i olie på en wok eller stor pande, til den er gennemstegt.','Kom grøntsager og hvidløg på, og steg 4 minutter – de skal stadig være sprøde.','Vend nudler, soja og chilisauce i, og varm det hele igennem.']},
{id:'std-spejlaeg-rugbroed',kat:'Æg & hurtigt',navn:'Spejlæg på rugbrød med avocado',foto:'fotos/retter/spejlaeg.jpg',tid:10,portioner:2,tags:['vegetar','hurtig'],
 ing:['4 skiver rugbrød','2 stk avocado','4 æg','1 spsk smør','1 knsp salt','1 knsp peber','1 knsp chiliflager'],
 trin:['Skær avocadoerne over, tag stenen ud, og mos kødet med en gaffel. Smag til med salt.','Smør avocado på rugbrødet.','Steg æggene i smør ved middel varme, til hviden er stiv.','Læg et spejlæg på hver skive, og drys med peber og lidt chili.']},
{id:'std-tunsalat-pita',kat:'Fisk',navn:'Tunsalat i pita',foto:'fotos/retter/tunsalat.jpg',tid:10,portioner:2,tags:['hurtig'],
 ing:['1 dåse tun i vand','2 spsk mayonnaise','2 spsk creme fraiche','0,5 løg','1 dåse majs','4 stk pitabrød','1 stk iceberg','1 knsp salt','1 knsp peber'],
 trin:['Hæld vandet fra tun og majs.','Hak løget meget fint.','Rør tun, mayonnaise, creme fraiche, løg og majs sammen. Smag til med salt og peber.','Rist pitabrødene kort, og skær dem op.','Fyld dem med salat og tunsalat.']},
{id:'std-omelet',kat:'Æg & hurtigt',navn:'Omelet med skinke, ost og purløg',foto:'fotos/retter/omelet.jpg',tid:10,portioner:1,tags:['hurtig'],
 ing:['3 æg','2 spsk mælk','50 g skinke','30 g revet ost','1 spsk purløg','1 tsk smør','1 knsp salt'],
 trin:['Pisk æg, mælk og salt sammen.','Smelt smørret på en pande ved middel varme, og hæld æggene på.','Træk forsigtigt æggemassen ind mod midten, så den stivner jævnt.','Drys skinke, ost og klippet purløg på den ene halvdel.','Fold omeletten sammen, og lad osten smelte et øjeblik.']},
{id:'std-tortillapizza',kat:'Mexicansk & street food',navn:'Tortilla-pizza',foto:'',tid:15,portioner:2,tags:['hurtig'],
 ing:['4 stk tortillas','4 spsk tomatpuré','1 tsk oregano','100 g skinke','150 g revet mozzarella'],
 trin:['Tænd ovnen på 225 °C.','Læg tortillas på en bageplade med bagepapir.','Rør tomatpuré med lidt vand og oregano, og smør det tyndt på.','Fordel skinke og ost – eller rester fra køleskabet.','Bag 6–8 minutter, til osten er smeltet og kanten sprød.']},
{id:'std-burgere',kat:'Kød & fars',navn:'Hjemmelavede burgere med ovnkartofler',foto:'fotos/retter/burger.jpg',tid:45,portioner:4,tags:[],
 ing:['500 g hakket oksekød','4 stk burgerboller','1 kg kartofler','2 spsk olie','1 stk iceberg','2 tomater','1 løg','4 skiver ost','4 spsk ketchup','1 tsk salt','1 knsp peber'],
 trin:['Tænd ovnen på 220 °C. Skær kartoflerne i både, vend dem i olie og salt, og bag dem i ca. 35 minutter.','Form kødet til 4 bøffer, lidt større end bollerne. Drys med salt og peber.','Steg bøfferne 3–4 minutter på hver side. Læg ost på til sidst.','Rist bollerne, og snit salat, tomat og løg.','Byg burgerne med ketchup og grønt, og server med ovnkartofler.']},
{id:'std-chili-con-carne',kat:'Kød & fars',navn:'Chili con carne',foto:'fotos/retter/chilicon.jpg',tid:40,portioner:4,tags:[],
 ing:['500 g hakket oksekød','1 løg','2 fed hvidløg','1 stk rød peberfrugt','2 tsk chilipulver','1 tsk spidskommen','2 dåser hakkede tomater','2 dåser kidneybønner','3 dl ris','2 dl creme fraiche','150 g nachos','1 tsk salt'],
 trin:['Kog risene efter pakken.','Brun kødet i en gryde med hakket løg, hvidløg og peberfrugt.','Rør chili og spidskommen i, og kom tomater og skyllede bønner i.','Lad det simre i 20 minutter. Smag til med salt.','Server med ris, creme fraiche og nachos.']},
{id:'std-dhal',kat:'Ris, korn & grød',navn:'Dhal (indisk linsegryde) med naanbrød',foto:'fotos/retter/dhal.jpg',tid:35,portioner:4,tags:['vegetar'],
 ing:['250 g røde linser','1 løg','3 fed hvidløg','1 spsk frisk ingefær','2 spsk olie','2 tsk karry','1 tsk gurkemeje','1 dåse kokosmælk','6 dl vand','1 stk bouillonterning','4 stk naanbrød','1 tsk salt'],
 trin:['Hak løg, hvidløg og ingefær, og svits dem i olie med karry og gurkemeje i 2 minutter.','Skyl linserne, og kom dem i gryden med kokosmælk, vand og bouillon.','Kog i ca. 20 minutter under omrøring, til linserne er møre og gryden tyk.','Smag til med salt.','Varm naanbrødene i ovnen, og server dem til.']},
{id:'std-groentsagstaerte',kat:'Grønt & vegetar',navn:'Grøntsagstærte med feta og spinat',foto:'fotos/retter/taerte.jpg',tid:60,portioner:4,tags:['vegetar'],
 ing:['1 pakke færdig tærtedej','250 g frossen spinat','150 g feta','1 løg','4 æg','2 dl mælk','1 knsp muskatnød','1 tsk salt','1 knsp peber'],
 trin:['Tænd ovnen på 200 °C. Læg dejen i en tærteform, og prik bunden med en gaffel.','Tø spinaten op, og pres vandet ud. Hak løget, og steg det blødt.','Fordel spinat, løg og smuldret feta i bunden.','Pisk æg, mælk, salt, peber og muskat sammen, og hæld det over.','Bag tærten i ca. 35 minutter, til fyldet er stivnet og gyldent.']},
{id:'std-quesadillas',kat:'Mexicansk & street food',navn:'Quesadillas med bønner, majs og cheddar',foto:'fotos/retter/quesadilla.jpg',tid:20,portioner:4,tags:['vegetar','hurtig'],
 ing:['8 stk tortillas','1 dåse sorte bønner','1 dåse majs','150 g revet cheddar','1 tsk spidskommen','1 spsk olie','2 dl creme fraiche'],
 trin:['Skyl bønner og majs, og bland dem med spidskommen.','Drys ost, bønner og majs på 4 tortillas, og læg en tortilla ovenpå hver.','Steg dem på en pande med lidt olie, ca. 2–3 minutter på hver side, til osten smelter.','Skær dem i trekanter, og server med creme fraiche.']},
{id:'std-falafel-pita',kat:'Mexicansk & street food',navn:'Pita med falafel og dressing',foto:'fotos/retter/falafel.jpg',tid:30,portioner:4,tags:['vegetar'],
 ing:['2 dåser kikærter','1 løg','2 fed hvidløg','1 bundt persille','2 tsk spidskommen','3 spsk hvedemel','3 spsk olie','4 stk pitabrød','2 dl yoghurt naturel','1 agurk','2 tomater','1 tsk salt'],
 trin:['Hæld vandet fra kikærterne, og blend dem groft med løg, hvidløg, persille, spidskommen, mel og salt.','Form små boller, og tryk dem lidt flade.','Steg dem i olie på en pande, ca. 3 minutter på hver side, til de er sprøde.','Rør yoghurt med lidt revet agurk og salt til en dressing.','Fyld pitabrødene med falafel, tomat, agurk og dressing.']}
];

